from abc import ABCMeta

from taf.ul.ettf.config.globals import IPHY0_LMP_IP, GNB_LMP_IP_2, AASHELL_PORT
from taf.ul.ettf.config.secrets import secrets


class AashellConfig(object):
    __metaclass__ = ABCMeta

    def address(self):
        pass

    def ports(self):
        pass

    def username(self):
        pass

    def password(self):
        pass


class EnbAashellConfig(AashellConfig):
    _address = GNB_LMP_IP_2
    _ports = [AASHELL_PORT]
    _username = secrets.MODULE_USERNAME
    _password = secrets.MODULE_PASSWORD

    def address(self):
        return self._address

    def ports(self):
        return self._ports

    def username(self):
        return self._username

    def password(self):
        return self._password


class SimulatorAashellConfig(AashellConfig):
    _address = IPHY0_LMP_IP
    _ports = [8023]
    _username = secrets.MODULE_USERNAME
    _password = secrets.MODULE_PASSWORD

    def address(self):
        return self._address

    def ports(self):
        return self._ports

    def username(self):
        return self._username

    def password(self):
        return self._password


class ConfigProvider(object):
    @staticmethod
    def nb():
        return EnbAashellConfig()

    @staticmethod
    def simulator():
        return SimulatorAashellConfig()
